<template>
  <div>
    <div class="page-header"><div><h2>进货与退货管理</h2><p>记录真实到货批次、进价和生产日期，并支持明细追溯及原单退货</p></div><div><el-button type="warning" plain @click="openReturn">新增进货退货单</el-button><el-button type="primary" @click="openCreate">新增进货单</el-button></div></div>
    <div class="metrics"><el-card><span>进货单</span><b>{{receipts.length}}</b></el-card><el-card><span>今日进货</span><b>¥{{money(todayAmount)}}</b></el-card><el-card><span>退货单</span><b>{{returns.length}}</b></el-card><el-card><span>当前明细金额</span><b>¥{{money(detailTotal)}}</b></el-card></div>
    <el-card class="panel">
      <el-tabs v-model="tab" @tab-change="tabChanged">
        <el-tab-pane label="进货单" name="receipts">
          <div class="toolbar"><el-input v-model="receiptKeyword" clearable placeholder="搜索单号、供应商、商品或批次" style="width:360px"/><span>实际到货后录入，价格以本次进货价为准</span></div>
          <el-table :data="filteredReceipts" stripe>
            <el-table-column type="expand"><template #default="s"><el-table :data="s.row.items" border size="small" class="inner-table"><el-table-column prop="product_name" label="商品"/><el-table-column label="数量"><template #default="c">{{number(c.row.quantity)}} {{c.row.unit_name}}</template></el-table-column><el-table-column label="进价"><template #default="c">¥{{money(c.row.unit_price)}}</template></el-table-column><el-table-column label="金额"><template #default="c">¥{{money(c.row.amount)}}</template></el-table-column><el-table-column prop="batch_no" label="批次"/><el-table-column prop="production_date" label="生产日期"/><el-table-column prop="expiry_date" label="到期日期"/></el-table></template></el-table-column>
            <el-table-column prop="receipt_no" label="进货单号" min-width="190"/><el-table-column prop="receipt_date" label="进货日期" width="115"/><el-table-column prop="supplier_name" label="供应商" min-width="160"/><el-table-column label="商品"><template #default="s">{{s.row.items.length}}项 · {{s.row.items.slice(0,2).map(i=>i.product_name).join('、')}}</template></el-table-column><el-table-column prop="warehouse" label="入库位置"/><el-table-column prop="creator_name" label="录入人" width="110"/><el-table-column label="进货金额" width="135"><template #default="s"><b class="amount">¥{{money(s.row.total_amount)}}</b></template></el-table-column><el-table-column label="操作" width="85"><template #default="s"><el-button link type="primary" @click="openEdit(s.row)">编辑</el-button></template></el-table-column>
          </el-table>
        </el-tab-pane>
        <el-tab-pane label="进货明细查询" name="details">
          <div class="detail-filter"><el-date-picker v-model="filters.dates" type="daterange" value-format="YYYY-MM-DD" start-placeholder="开始日期" end-placeholder="结束日期"/><el-select v-model="filters.supplier_id" clearable filterable placeholder="全部供应商"><el-option v-for="s in options.suppliers" :key="s.id" :label="s.name" :value="s.id"/></el-select><el-select v-model="filters.product_id" clearable filterable placeholder="全部商品"><el-option v-for="p in options.products" :key="p.id" :label="p.name" :value="p.id"/></el-select><el-input v-model="filters.keyword" clearable placeholder="单号/商品/批次"/><el-button type="primary" @click="loadDetails">查询</el-button><el-button @click="clearFilters">重置</el-button></div>
          <el-table :data="details" stripe show-summary :summary-method="detailSummary"><el-table-column prop="receipt_date" label="进货日期" width="115"/><el-table-column prop="receipt_no" label="进货单号" min-width="190"/><el-table-column prop="supplier_name" label="供应商"/><el-table-column prop="product_name" label="商品"/><el-table-column prop="category" label="分类"/><el-table-column label="数量"><template #default="s">{{number(s.row.quantity)}} {{s.row.unit_name}}</template></el-table-column><el-table-column label="单价"><template #default="s">¥{{money(s.row.unit_price)}}</template></el-table-column><el-table-column label="金额"><template #default="s"><b>¥{{money(s.row.amount)}}</b></template></el-table-column><el-table-column prop="batch_no" label="批次"/><el-table-column prop="production_date" label="生产日期"/><el-table-column prop="expiry_date" label="到期日期"/><el-table-column prop="warehouse" label="入库位置"/></el-table>
        </el-tab-pane>
        <el-tab-pane label="进货退货单" name="returns">
          <el-table :data="returns" stripe><el-table-column type="expand"><template #default="s"><el-table :data="s.row.items" border size="small" class="inner-table"><el-table-column prop="product_name" label="商品"/><el-table-column label="退货数量"><template #default="c">{{number(c.row.quantity)}} {{c.row.unit_name}}</template></el-table-column><el-table-column label="退货单价"><template #default="c">¥{{money(c.row.unit_price)}}</template></el-table-column><el-table-column prop="batch_no" label="批次"/><el-table-column prop="remark" label="明细备注"/></el-table></template></el-table-column><el-table-column prop="return_no" label="退货单号" min-width="190"/><el-table-column prop="return_date" label="退货日期" width="115"/><el-table-column prop="supplier_name" label="供应商"/><el-table-column prop="receipt_no" label="原进货单" min-width="185"/><el-table-column prop="reason" label="退货原因"/><el-table-column prop="creator_name" label="经办人"/><el-table-column label="退货金额"><template #default="s"><b class="return-amount">¥{{money(s.row.total_amount)}}</b></template></el-table-column></el-table>
        </el-tab-pane>
      </el-tabs>
    </el-card>

    <el-dialog v-model="receiptVisible" :title="receiptForm.id?'编辑进货单':'快捷新增进货单'" width="96%" top="3vh" destroy-on-close>
      <el-alert title="选中商品后自动带出基础单位、参考进价和保质期；最后一行选完会自动续行。" type="info" :closable="false" show-icon/>
      <el-form label-position="top" class="entry-form"><el-row :gutter="14"><el-col :span="8"><el-form-item label="供应商" required><el-select v-model="receiptForm.supplier_id" filterable style="width:100%"><el-option v-for="s in options.suppliers" :key="s.id" :label="s.name" :value="s.id"/></el-select></el-form-item></el-col><el-col :span="5"><el-form-item label="进货日期" required><el-date-picker v-model="receiptForm.receipt_date" value-format="YYYY-MM-DD" style="width:100%"/></el-form-item></el-col><el-col :span="6"><el-form-item label="入库位置"><el-input v-model="receiptForm.warehouse" placeholder="如 冷库A区"/></el-form-item></el-col></el-row></el-form>
      <el-table :data="receiptForm.items" border><el-table-column type="index" width="48"/><el-table-column label="商品" min-width="210"><template #default="s"><el-select v-model="s.row.product_id" filterable placeholder="名称/别名/分类" style="width:100%" @change="selectReceiptProduct(s.row)"><el-option v-for="p in availableProducts(s.row)" :key="p.id" :label="productLabel(p)" :value="p.id"/></el-select></template></el-table-column><el-table-column label="单位" width="115"><template #default="s"><el-select v-model="s.row.unit_id" @change="changeReceiptUnit(s.row)"><el-option v-for="u in productOf(s.row)?.units||[]" :key="u.id" :label="u.name" :value="u.id"/></el-select></template></el-table-column><el-table-column label="数量" width="125"><template #default="s"><el-input-number v-model="s.row.quantity" :min="0.01" :precision="2" controls-position="right"/></template></el-table-column><el-table-column label="进货单价" width="140"><template #default="s"><el-input-number v-model="s.row.unit_price" :min="0" :precision="2" controls-position="right"/></template></el-table-column><el-table-column label="批次号" min-width="125"><template #default="s"><el-input v-model="s.row.batch_no" placeholder="可选"/></template></el-table-column><el-table-column label="生产日期" width="145"><template #default="s"><el-date-picker v-model="s.row.production_date" value-format="YYYY-MM-DD" style="width:130px"/></template></el-table-column><el-table-column label="保质期/天" width="125"><template #default="s"><el-input-number v-model="s.row.shelf_life_days" :min="1" controls-position="right"/></template></el-table-column><el-table-column label="小计" width="110"><template #default="s"><b>¥{{money(s.row.quantity*s.row.unit_price)}}</b></template></el-table-column><el-table-column width="60"><template #default="s"><el-button v-if="s.row.product_id" link type="danger" @click="removeReceiptLine(s.$index)">移除</el-button></template></el-table-column></el-table>
      <div class="dialog-bottom"><el-input v-model="receiptForm.notes" type="textarea" :rows="2" placeholder="验收情况、送货单号等备注"/><b>合计 ¥{{money(receiptTotal)}}</b></div>
      <template #footer><el-button @click="receiptVisible=false">取消</el-button><el-button type="primary" @click="saveReceipt">保存进货单</el-button></template>
    </el-dialog>

    <el-dialog v-model="returnVisible" title="新增进货退货单" width="900px" top="5vh">
      <el-alert title="优先引用原进货单，系统会校验供应商、批次和可退数量，避免重复超量退货。" type="warning" :closable="false" show-icon/>
      <el-form label-position="top" class="entry-form"><el-row :gutter="14"><el-col :span="10"><el-form-item label="引用原进货单" required><el-select v-model="returnForm.receipt_id" filterable style="width:100%" @change="selectReturnReceipt"><el-option v-for="r in receipts" :key="r.id" :label="`${r.receipt_no} · ${r.supplier_name} · ¥${money(r.total_amount)}`" :value="r.id"/></el-select></el-form-item></el-col><el-col :span="5"><el-form-item label="退货日期"><el-date-picker v-model="returnForm.return_date" value-format="YYYY-MM-DD" style="width:100%"/></el-form-item></el-col><el-col :span="9"><el-form-item label="退货原因" required><el-input v-model="returnForm.reason" placeholder="品质异常、数量多送等"/></el-form-item></el-col></el-row></el-form>
      <el-table :data="returnForm.items" border><el-table-column prop="product_name" label="商品"/><el-table-column label="原进货"><template #default="s">{{number(s.row.source_quantity)}} {{s.row.unit_name}}</template></el-table-column><el-table-column prop="batch_no" label="批次"/><el-table-column label="退货数量"><template #default="s"><el-input-number v-model="s.row.quantity" :min="0" :max="s.row.source_quantity" :precision="2"/></template></el-table-column><el-table-column label="退货单价"><template #default="s"><el-input-number v-model="s.row.unit_price" :min="0" :precision="2"/></template></el-table-column><el-table-column label="备注"><template #default="s"><el-input v-model="s.row.remark"/></template></el-table-column></el-table>
      <el-input v-model="returnForm.notes" type="textarea" :rows="2" placeholder="补充说明" class="return-notes"/>
      <template #footer><el-button @click="returnVisible=false">取消</el-button><el-button type="primary" @click="saveReturn">确认生成退货单</el-button></template>
    </el-dialog>
  </div>
</template>

<script setup>
import { computed,onMounted,reactive,ref } from 'vue'
import { ElMessage } from 'element-plus'
import { createGoodsReceipt,createPurchaseReturn,getGoodsReceipts,getInboundDetails,getInboundOptions,getPurchaseReturns,updateGoodsReceipt } from '@/api'
const today=()=>new Date().toLocaleDateString('sv-SE'),number=v=>Number(v||0).toLocaleString('zh-CN',{maximumFractionDigits:2}),money=v=>Number(v||0).toLocaleString('zh-CN',{minimumFractionDigits:2,maximumFractionDigits:2})
const tab=ref('receipts'),receipts=ref([]),returns=ref([]),details=ref([]),receiptVisible=ref(false),returnVisible=ref(false),receiptKeyword=ref(''),detailTotal=ref(0)
const options=reactive({suppliers:[],products:[]}),filters=reactive({dates:[],supplier_id:null,product_id:null,keyword:''})
const emptyLine=()=>({product_id:null,unit_id:null,quantity:1,unit_price:0,batch_no:'',production_date:null,shelf_life_days:null,remark:''})
const blankReceipt=()=>({id:null,supplier_id:null,receipt_date:today(),warehouse:'',notes:'',items:[emptyLine()]})
const receiptForm=reactive(blankReceipt()),returnForm=reactive({receipt_id:null,supplier_id:null,return_date:today(),reason:'',notes:'',items:[]})
const todayAmount=computed(()=>receipts.value.filter(r=>r.receipt_date===today()).reduce((n,r)=>n+r.total_amount,0)),receiptTotal=computed(()=>receiptForm.items.filter(i=>i.product_id).reduce((n,i)=>n+Number(i.quantity||0)*Number(i.unit_price||0),0))
const filteredReceipts=computed(()=>{const q=receiptKeyword.value.toLowerCase();return receipts.value.filter(r=>!q||`${r.receipt_no}${r.supplier_name}${r.items.map(i=>`${i.product_name}${i.batch_no||''}`).join('')}`.toLowerCase().includes(q))})
const productOf=line=>options.products.find(p=>p.id===line.product_id),productLabel=p=>[p.name,...(p.aliases||[]),p.category].filter(Boolean).join(' · ')
const availableProducts=()=>options.products
const ensureLine=()=>{if(!receiptForm.items.length||receiptForm.items.at(-1).product_id)receiptForm.items.push(emptyLine())}
const selectReceiptProduct=line=>{const p=productOf(line);if(!p)return;const u=p.units.find(x=>x.is_base)||p.units[0];line.unit_id=u?.id||null;line.unit_price=u?.reference_purchase_price||0;line.shelf_life_days=p.shelf_life_days;ensureLine()}
const changeReceiptUnit=line=>{const u=productOf(line)?.units.find(x=>x.id===line.unit_id);line.unit_price=u?.reference_purchase_price||0}
const removeReceiptLine=i=>{receiptForm.items.splice(i,1);ensureLine()}
const load=async()=>{const[a,b,c]=await Promise.all([getInboundOptions(),getGoodsReceipts(),getPurchaseReturns()]);Object.assign(options,a);receipts.value=b;returns.value=c}
const openCreate=()=>{Object.assign(receiptForm,blankReceipt());receiptVisible.value=true}
const openEdit=row=>{Object.assign(receiptForm,{id:row.id,supplier_id:row.supplier_id,receipt_date:row.receipt_date,warehouse:row.warehouse||'',notes:row.notes||'',items:[...row.items.map(i=>({...i})),emptyLine()]});receiptVisible.value=true}
const receiptPayload=()=>({supplier_id:receiptForm.supplier_id,receipt_date:receiptForm.receipt_date,warehouse:receiptForm.warehouse||null,notes:receiptForm.notes||null,items:receiptForm.items.filter(i=>i.product_id).map(i=>({product_id:i.product_id,unit_id:i.unit_id,quantity:i.quantity,unit_price:i.unit_price,batch_no:i.batch_no||null,production_date:i.production_date||null,shelf_life_days:i.shelf_life_days||null,remark:i.remark||null}))})
const saveReceipt=async()=>{const payload=receiptPayload();if(!payload.supplier_id)return ElMessage.warning('请选择供应商');if(!payload.items.length)return ElMessage.warning('请至少录入一个商品');if(payload.items.some(i=>!i.unit_id||i.quantity<=0))return ElMessage.warning('请完整填写商品单位和数量');receiptForm.id?await updateGoodsReceipt(receiptForm.id,payload):await createGoodsReceipt(payload);ElMessage.success('进货单已保存');receiptVisible.value=false;await load();if(tab.value==='details')await loadDetails()}
const loadDetails=async()=>{const result=await getInboundDetails({date_from:filters.dates?.[0],date_to:filters.dates?.[1],supplier_id:filters.supplier_id,product_id:filters.product_id,keyword:filters.keyword||undefined});details.value=result.rows;detailTotal.value=result.total_amount}
const clearFilters=()=>{Object.assign(filters,{dates:[],supplier_id:null,product_id:null,keyword:''});loadDetails()}
const tabChanged=name=>{if(name==='details')loadDetails()}
const detailSummary=({columns})=>columns.map((_,i)=>i===0?'当前筛选合计':i===7?`¥${money(detailTotal.value)}`:'')
const openReturn=()=>{Object.assign(returnForm,{receipt_id:null,supplier_id:null,return_date:today(),reason:'',notes:'',items:[]});returnVisible.value=true}
const selectReturnReceipt=id=>{const r=receipts.value.find(x=>x.id===id);if(!r)return;returnForm.supplier_id=r.supplier_id;returnForm.items=r.items.map(i=>({product_id:i.product_id,product_name:i.product_name,unit_id:i.unit_id,unit_name:i.unit_name,source_quantity:i.quantity,quantity:0,unit_price:i.unit_price,batch_no:i.batch_no||null,remark:''}))}
const saveReturn=async()=>{const items=returnForm.items.filter(i=>Number(i.quantity)>0).map(i=>({product_id:i.product_id,unit_id:i.unit_id,quantity:i.quantity,unit_price:i.unit_price,batch_no:i.batch_no,remark:i.remark||null}));if(!returnForm.receipt_id)return ElMessage.warning('请选择原进货单');if(!returnForm.reason.trim())return ElMessage.warning('请填写退货原因');if(!items.length)return ElMessage.warning('请填写至少一个商品的退货数量');await createPurchaseReturn({supplier_id:returnForm.supplier_id,receipt_id:returnForm.receipt_id,return_date:returnForm.return_date,reason:returnForm.reason.trim(),notes:returnForm.notes||null,items});ElMessage.success('退货单已生成');returnVisible.value=false;await load();tab.value='returns'}
onMounted(async()=>{await load();await loadDetails()})
</script>

<style scoped>
.metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin-bottom:16px}.metrics span,.metrics b{display:block}.metrics span{color:#7d899b}.metrics b{font-size:23px;margin-top:7px}.toolbar{display:flex;align-items:center;gap:16px;margin-bottom:14px}.toolbar span{color:#8490a3}.inner-table{margin:10px 42px;width:calc(100% - 84px)}.amount{color:#df6535}.return-amount{color:#d94f4f}.detail-filter{display:grid;grid-template-columns:260px 190px 190px 1fr auto auto;gap:10px;margin-bottom:15px}.entry-form{margin-top:16px}.dialog-bottom{display:grid;grid-template-columns:1fr 260px;gap:20px;align-items:end;margin-top:15px}.dialog-bottom b{text-align:right;font-size:22px;color:#df6535}.return-notes{margin-top:15px}
</style>
